#include <iostream>
#include "2DAImporter.h"
#include "Streams/FileStream.h"
int main() {
    GemRB::p2DAImporter data;
    if (!data.Open(GemRB::FileStream::OpenFile("hello.2da"))) return 1;
    if (data.GetRowCount()!=1 || data.GetColumnCount(0)!=2) return 2;
    if (data.GetColumnName(0)!="GREETING" || data.GetColumnName(1)!="TARGET") return 3;
    std::cout << data.QueryField(0,0) << ' ' << data.QueryField(0,1) << '\n';
}
